export const MAIN_HTML = "<article class=\"hub\">\n\n<header class=\"hub-head\">\n<h1>Icing Forecasts: CIP, FIP, Freezing Level, and Icing Intensity</h1>\n<p class=\"byline\">PlaneWX · Updated September 29, 2026</p>\n\n<p class=\"answer\">The <a class=\"gl\" href=\"#gl-cip\" data-gl=\"cip\">CIP</a> (Current Icing Product) is an hourly, automated 3D diagnosis of icing, and the <a class=\"gl\" href=\"#gl-fip\" data-gl=\"fip\">FIP</a> (Forecast Icing Product) is its forecast counterpart out to 18 hours. Both show icing probability, severity, and supercooled large drop threat from 1,000 ft MSL to FL300. Read them with the freezing level, AIRMETs, SIGMETs, and PIREPs&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.5 and 27.13]</a></span>.</p>\n\n<section class=\"takeaways\" aria-label=\"Key takeaways\">\n<h2>Key takeaways</h2>\n<ul>\n  <li>CIP and FIP are computer products with no forecaster changes. Use them together with AIRMETs, SIGMETs, and PIREPs, not instead of them&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.5 and 27.13]</a></span>.</li>\n  <li>The intensity words differ by product. CIP and FIP \"heavy\" is an accumulation rate&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>; the AIM's \"severe\" is defined by what happens to your airplane&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span>.</li>\n  <li>Know the freezing level before you go. It tells you where a warmer escape altitude is, if there is one&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-1c]</a><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span>.</li>\n</ul>\n</section>\n</header>\n\n<aside class=\"keyfacts\" aria-label=\"Key facts about icing forecasts\">\n<details class=\"kf-box\" id=\"key-facts\" open>\n<summary><h2>Key facts</h2></summary>\n<ol>\n  <li>The <a class=\"gl\" href=\"#gl-cip\" data-gl=\"cip\">CIP</a> is an hourly 3D icing diagnosis from satellite, radar, METARs, PIREPs, and model data&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>.</li>\n  <li>The <a class=\"gl\" href=\"#gl-fip\" data-gl=\"fip\">FIP</a> forecasts the same products from computer models through 18 hours&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13]</a></span>.</li>\n  <li>Both run from 1,000 ft MSL to FL300, with no forecaster changes&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.5 and 27.13]</a></span>.</li>\n  <li>FIP severity categories are trace, light, moderate, and heavy&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.2]</a></span>.</li>\n  <li>CIP and FIP intensities show accumulation rate, not aircraft performance; AIRMET and SIGMET icing terms do refer to aircraft impact&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>.</li>\n  <li>AIRMET Zulu covers moderate icing; SIGMETs cover severe icing&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.7]</a></span>.</li>\n  <li>The <a class=\"gl\" href=\"#gl-frzlvl\" data-gl=\"frzlvl\">freezing level</a> is the lowest altitude where the air reaches 0°C; there can be several&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.4]</a></span>.</li>\n  <li>Freezing level graphics update hourly, in hundreds of feet MSL&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.12]</a></span>.</li>\n  <li><a class=\"gl\" href=\"#gl-sld\" data-gl=\"sld\">SLD</a> are drops larger than 50 micrometers, below 0°C&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.3]</a></span>.</li>\n  <li>Severe icing requires immediate exit, by regulation&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span>.</li>\n</ol>\n<p class=\"kf-foot\">Hover, focus, or tap any dotted term for a definition and its official source.</p>\n<div class=\"kf-fade\" aria-hidden=\"true\"></div>\n</details>\n</aside>\n\n<div class=\"hub-body\">\n<p>Structural icing adds weight and drag and takes away lift. The AIM says the result is \"an increase in stall speed and a deterioration of aircraft performance\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span>. This page explains the NWS icing products, the freezing level, and the intensity words pilots see in forecasts and reports. The Aviation Weather Center's icing web page was not available when this page was written, so the product descriptions come from the FAA Aviation Weather Handbook, with the AIM, the FAA's icing pilot guide (AC 91-74B), and NWS Instruction 10-811&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1]</a><a class=\"cite\" href=\"#ref-2\">[2]</a><a class=\"cite\" href=\"#ref-3\">[3]</a><a class=\"cite\" href=\"#ref-4\">[4]</a></span>.</p>\n\n<h2 id=\"products\">Which products carry icing information?</h2>\n<p>The Handbook's Table 3-10 lists every product with in-flight icing information. The main ones&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.7]</a></span>:</p>\n<div class=\"table-wrap\"><table class=\"stack\" role=\"table\">\n<thead role=\"rowgroup\"><tr role=\"row\"><th scope=\"col\" role=\"columnheader\">Product</th><th scope=\"col\" role=\"columnheader\">Kind</th><th scope=\"col\" role=\"columnheader\">What it says about icing</th></tr></thead>\n<tbody role=\"rowgroup\">\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\"><a class=\"gl\" href=\"#gl-pirep\" data-gl=\"pirep\">PIREP</a></th><td role=\"cell\" data-label=\"Kind\">Observation</td><td role=\"cell\" data-label=\"What it says about icing\">Intensity, type, and altitude actually met. Severe icing makes it an urgent report&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.7]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\"><a class=\"gl\" href=\"#gl-cip\" data-gl=\"cip\">CIP</a></th><td role=\"cell\" data-label=\"Kind\">Automated analysis</td><td role=\"cell\" data-label=\"What it says about icing\">Hourly 3D diagnosis of icing probability, severity, and supercooled large drop threat&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 3.4.2.7 and 25.5]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\"><a class=\"gl\" href=\"#gl-fip\" data-gl=\"fip\">FIP</a></th><td role=\"cell\" data-label=\"Kind\">Automated forecast</td><td role=\"cell\" data-label=\"What it says about icing\">The same products forecast out to 18 hours from computer models&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\"><a class=\"gl\" href=\"#gl-zulu\" data-gl=\"zulu\">AIRMET Zulu</a></th><td role=\"cell\" data-label=\"Kind\">Advisory</td><td role=\"cell\" data-label=\"What it says about icing\">\"AIRMET Zulu depicts areas of active or expected moderate icing.\" It also carries freezing level information&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.7]</a><a class=\"cite\" href=\"#ref-4\">[4, sec. 7.1]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\"><a class=\"gl\" href=\"#gl-sigmet\" data-gl=\"sigmet\">SIGMET</a></th><td role=\"cell\" data-label=\"Kind\">Advisory</td><td role=\"cell\" data-label=\"What it says about icing\">\"Non-convective SIGMETs are issued for severe icing.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.7]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\"><a class=\"gl\" href=\"#gl-csigmet\" data-gl=\"csigmet\">Convective SIGMET</a></th><td role=\"cell\" data-label=\"Kind\">Advisory</td><td role=\"cell\" data-label=\"What it says about icing\">\"Possible severe icing is implied within the convective SIGMET area.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.7]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\"><a class=\"gl\" href=\"#gl-cwa\" data-gl=\"cwa\">CWA</a></th><td role=\"cell\" data-label=\"Kind\">Advisory</td><td role=\"cell\" data-label=\"What it says about icing\">\"May be issued for moderate or greater icing.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.7]</a></span></td></tr>\n</tbody></table></div>\n<p>Forecasters write the advisories. CIP and FIP are automated: the NWS produces them from model data, and observations for the CIP, \"with no forecaster modifications\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>. The AIRMET and SIGMET rules are in the <a href=\"/learn/aviation-weather/airmet-sigmet\">advisories guide</a>.</p>\n\n<h2 id=\"cip\">What is the Current Icing Product (CIP)?</h2>\n<p>\"The CIP combines weather satellite, weather radar, METAR, PIREPs and NWS model data to provide an hourly 3D diagnosis of the icing environment.\" Its graphics cover the contiguous U.S., much of Canada and Mexico, and their coastal waters&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>.</p>\n<p>The CIP is generated for select altitudes from 1,000 ft MSL to FL300. You can view one altitude at a time or a composite of all of them, called the \"maximum\" or \"max\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>. Icing PIREPs are plotted on a single-altitude chart if they are within 1,000 ft of that altitude and within 75 minutes of the chart's valid time; negative reports are left off to reduce clutter&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>.</p>\n<h3>Why the \"C\" doesn't mean now</h3>\n<p>The Handbook warns that \"while the 'C' in CIP stands for 'current,' the product does not show the current conditions, rather it depicts the computer’s expected conditions at the valid time shown on the product.\" \"This valid time can be an hour old or more depending on when it is received by the user.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span> Check the valid time every time.</p>\n<p>And the Handbook's usage rule: \"The CIP should be used in conjunction with the report and forecast information contained in an AIRMET and SIGMET.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span></p>\n\n<h2 id=\"fip\">What is the Forecast Icing Product (FIP)?</h2>\n<p>The FIP is the CIP's forecast counterpart. \"The FIP provides the same suite of products as the CIP (see Section 25.5), describing the icing environment in the future and being solely NWP model based.\" It is available at select forecast times through 18 hours, from 1,000 ft MSL to FL300, and it too should be used with AIRMETs and SIGMETs&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13]</a></span>. The FAA's icing guide describes both products the same way: \"This product is automatically produced with no human modification.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 1-3]</a></span></p>\n<h3>The three icing graphics</h3>\n<p>Both products come as a suite of graphics&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.5 and 27.13]</a></span>:</p>\n<div class=\"table-wrap\"><table class=\"stack\" role=\"table\">\n<thead role=\"rowgroup\"><tr role=\"row\"><th scope=\"col\" role=\"columnheader\">Graphic</th><th scope=\"col\" role=\"columnheader\">What it shows</th><th scope=\"col\" role=\"columnheader\">Scale</th></tr></thead>\n<tbody role=\"rowgroup\">\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\">Icing Probability</th><td role=\"cell\" data-label=\"What it shows\">The chance of icing of any intensity&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.1]</a></span></td><td role=\"cell\" data-label=\"Scale\">\"Probabilities range from 0 percent (no icing expected) to 85 percent or greater (nearly certain icing).\"</td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\">Icing Severity</th><td role=\"cell\" data-label=\"What it shows\">How strong the icing is likely to be where icing is possible&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.2]</a></span></td><td role=\"cell\" data-label=\"Scale\">Trace, light, moderate, and heavy&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.2]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\">Icing Severity plus SLD</th><td role=\"cell\" data-label=\"What it shows\">Severity, plus where a <a class=\"gl\" href=\"#gl-sld\" data-gl=\"sld\">SLD</a> threat exists&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.3]</a></span></td><td role=\"cell\" data-label=\"Scale\">The same four categories, with SLD areas marked&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.3]</a></span></td></tr>\n</tbody></table></div>\n<p>The Severity plus SLD product \"can help in determining the threat of SLD, which is particularly hazardous to some aircraft.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span></p>\n<p class=\"note\">Source conflict, noted: the Handbook's CIP and FIP sections describe three graphics on the Aviation Weather Center website, while its Table 3-10 lists five, adding Icing Severity with probability over 25% and over 50%&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 3.4.2.7, 25.5, and 27.13]</a></span>. The website version may change; this page describes the three core graphics.</p>\n\n<h2 id=\"intensity\">What do icing intensity words mean?</h2>\n<p>Two different scales use similar words, and mixing them up is a real risk.</p>\n<h3>CIP and FIP severity: an accumulation rate</h3>\n<p>The FIP uses trace, light, moderate, and heavy&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.2]</a></span>. \"Heavy icing is defined as the accretion of ¼ inch of ice on the airfoil in < 15 minutes.\" \"This is a relative value and the use of which should take into account the airframe and the level of icing protection provided by the aircraft.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13]</a></span> The Handbook adds that because ice accumulation varies with wing shape, \"the icing intensity categories depicted in CIPs and FIPs (e.g., none, light, moderate, heavy) is only a broad-brushed indication of ice accumulation rate, and not necessarily of aircraft performance.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span></p>\n<h3>AIM intensity: what happens to your airplane</h3>\n<p>\"The icing terms used in SIGMETs and AIRMETs do refer to icing impact on aircraft.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span> Those terms, and the ones pilots use in PIREPs, come from the AIM&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span>:</p>\n<div class=\"table-wrap\"><table class=\"stack\" role=\"table\">\n<thead role=\"rowgroup\"><tr role=\"row\"><th scope=\"col\" role=\"columnheader\">AIM intensity</th><th scope=\"col\" role=\"columnheader\">Representative rate, outer wing (inches per hour)</th><th scope=\"col\" role=\"columnheader\">AIM guidance</th></tr></thead>\n<tbody role=\"rowgroup\">\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\">Trace</th><td role=\"cell\" data-label=\"Representative rate, outer wing (inches per hour)\">Less than 1/4 (6 mm)</td><td role=\"cell\" data-label=\"AIM guidance\">Consider exiting before it gets worse&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\">Light</th><td role=\"cell\" data-label=\"Representative rate, outer wing (inches per hour)\">1/4 to 1 (0.6 to 2.5 cm)</td><td role=\"cell\" data-label=\"AIM guidance\">Consider exiting&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\">Moderate</th><td role=\"cell\" data-label=\"Representative rate, outer wing (inches per hour)\">1 to 3 (2.5 to 7.5 cm)</td><td role=\"cell\" data-label=\"AIM guidance\">Consider exiting as soon as possible&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span></td></tr>\n<tr role=\"row\"><th scope=\"row\" role=\"rowheader\">Severe</th><td role=\"cell\" data-label=\"Representative rate, outer wing (inches per hour)\">More than 3 (7.5 cm)</td><td role=\"cell\" data-label=\"AIM guidance\">\"By regulation, immediate exit is required.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span></td></tr>\n</tbody></table></div>\n<p>\"Severe icing is aircraft dependent, as are the other categories of icing intensity.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span> The full definitions, with ice types, are in the <a href=\"/learn/aviation-weather/pirep#icing\">PIREP guide</a>.</p>\n<p class=\"note\">Source conflict, noted: the Handbook's CIP section lists the categories as none, light, moderate, and heavy, while its FIP section lists trace, light, moderate, and heavy&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.5 and 27.13.2]</a></span>. This page follows the FIP section, the more detailed one. Either way, the top CIP and FIP category is \"heavy,\" not \"severe.\"</p>\n\n<h2 id=\"freezing-level\">What is the freezing level, and where do you find it?</h2>\n<p>\"The freezing level is the lowest altitude in the atmosphere over a given location at which the air temperature reaches 0°C.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.4]</a></span> <a href=\"/learn/aviation-weather/atmospheric-stability\">Temperature inversions</a> aloft can change the normal relationship between altitude and temperature&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-1c]</a></span>, and where the surface is below freezing with warmer air above, the graphics show multiple freezing levels&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.4]</a></span>.</p>\n<h3>Freezing level graphics</h3>\n<p>The analysis and forecast graphics are updated hourly from NWS computer models. Colors show the height of the lowest freezing level in hundreds of feet MSL. \"Regions with white indicate the surface and the entire depth of the atmosphere are below freezing.\" Hatched or spotted areas show a below-freezing surface with multiple freezing levels aloft&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.4 and 27.12]</a></span>. The forecasts \"supplement the forecast freezing level information contained in the icing AIRMETs.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.12]</a></span></p>\n<h3>Other sources</h3>\n<ul>\n  <li><strong>AIRMETs.</strong> NWS Instruction 10-811 says freezing level information is included: multiple freezing levels, where the lowest is the declared one; areas with multiple freezing levels; and \"Range of freezing levels over the area is included.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-4\">[4, sec. 7.1]</a></span></li>\n  <li><strong>Winds aloft.</strong> \"Freezing levels can be determined from the winds aloft forecast.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-1g]</a></span> Look where the temperature changes sign between levels (<a href=\"/learn/aviation-weather/winds-aloft\">winds aloft guide</a>).</li>\n  <li><strong>PIREPs.</strong> Outside air temperature at a known altitude is a direct check. The FAA's icing guide calls PIREPs \"generally the most useful as they are factual weather reports for specific times and places.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-1]</a></span></li>\n  <li><strong>Radar.</strong> \"Bright band is a distinct feature observed by radar that denotes the freezing (melting) level.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 15.2.15.1.5]</a></span> See the <a href=\"/learn/aviation-weather/weather-radar\">radar guide</a>.</li>\n</ul>\n<p class=\"note\">Source conflict, noted: the FAA Aviation Weather Handbook and NWS Instruction 10-811 give different height intervals for the lowest freezing levels in AIRMETs&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 3.4.2.8]</a><a class=\"cite\" href=\"#ref-4\">[4, sec. 7.1]</a></span>. This page states no interval. Read the heights in the current AIRMET or G-AIRMET itself.</p>\n<h3>Why the freezing level matters</h3>\n<p>\"It is critically important for pilots to obtain the freezing levels for the areas in which they will be flying to be able to make educated decisions on how to exit icing conditions if they are encountered.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-1c]</a></span> The AIM agrees: \"Proper preflight action includes obtaining information on the freezing level and the above freezing levels in precipitation areas.\" It also warns that the escape altitude is not always down: \"This 'warmer' altitude may not always be a lower altitude.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span> Freezing rain means warm air above you.</p>\n\n<h2 id=\"sld\">What are supercooled large drops (SLD)?</h2>\n<p>The Handbook: \"SLD is defined as supercooled water droplets larger than 50 micrometers in diameter.\" They include freezing drizzle and freezing rain aloft&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.3]</a></span>. The AIM gives the same size as 0.05 mm&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-20]</a></span>. They matter because \"SLD ice tends to form aft, beyond the reach of deicing equipment.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 20.3.2.1]</a></span> That is why the CIP and FIP mark SLD threat areas separately.</p>\n\n<h2 id=\"field-reference\">Where are the official icing product descriptions?</h2>\n<section class=\"fieldref\" aria-labelledby=\"fieldref-h\">\n<h3 id=\"fieldref-h\">Official icing product descriptions</h3>\n<ul>\n  <li><strong>Start here:</strong> <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=365\">FAA Aviation Weather Handbook, Sections 25.4 and 25.5 (freezing level analysis and CIP, PDF pages 365 to 366)</a> and <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=454\">Sections 27.12 and 27.13 (freezing level forecasts and FIP, PDF pages 454 to 455)</a>&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.4 to 27.13.3]</a></span>.</li>\n  <li><a href=\"https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap7_section_1.html#7-1-19\">AIM 7-1-19, PIREPs Relating to Airframe Icing</a>, and <a href=\"https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap7_section_1.html#7-1-20\">7-1-20, Definitions of Inflight Icing Terms</a>&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2]</a></span>.</li>\n  <li><a href=\"https://www.faa.gov/documentLibrary/media/Advisory_Circular/AC_91-74B.pdf\">AC 91-74B, Pilot Guide: Flight in Icing Conditions</a>&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3]</a></span>.</li>\n  <li><a href=\"https://www.weather.gov/media/directives/010_pdfs/pd01008011curr.pdf\">NWS Instruction 10-811, Section 7.1</a>, for AIRMET icing and freezing level content&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-4\">[4, sec. 7.1]</a></span>.</li>\n</ul>\n<p class=\"status\">Links checked September 29, 2026: all returned HTTP 200.</p>\n</section>\n\n<h2>Where do icing forecasts mislead pilots?</h2>\n<ul>\n  <li><strong>The valid time is older than you think.</strong> A CIP can be an hour old or more when you see it&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>.</li>\n  <li><strong>Broad brush.</strong> CIP and FIP intensity is an accumulation rate, not a statement about your wing&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>.</li>\n  <li><strong>No forecaster in the loop.</strong> CIP and FIP are automated&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.5 and 27.13]</a></span>. AIRMETs and SIGMETs carry a forecaster's judgment.</li>\n  <li><strong>Absence of reports.</strong> \"nor can a report of no icing assure the absence of icing conditions at a later time\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-20]</a></span>.</li>\n  <li><strong>The human factor.</strong> The Handbook ends its FIP section plainly: \"The ultimate safety factor is the vigilance demonstrated by the pilot in potential icing situations.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13]</a></span></li>\n</ul>\n\n<h2>How do you use icing forecasts in a go/no-go decision?</h2>\n<p>The decision is yours as pilot in command, and it starts with what your airplane is approved for. A few habits:</p>\n<ul>\n  <li><strong>Find the freezing level and the tops.</strong> Together they tell you whether a climb or descent gets you out. In stratiform clouds, icing is often \"confined to a relatively thin layer, either climbing or descending may be effective in exiting the icing conditions within the clouds.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-1h]</a></span></li>\n  <li><strong>Layer the products.</strong> AIRMET Zulu and SIGMETs first, then CIP and FIP for detail, then PIREPs to check them (<a href=\"/learn/aviation-weather/pirep\">PIREP guide</a>).</li>\n  <li><strong>Treat SLD as its own hazard.</strong> Freezing drizzle or freezing rain aloft changes the plan&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 20.3.2.1]</a></span>.</li>\n  <li><strong>Write down your out.</strong> A <a class=\"gl\" href=\"#gl-frat\" data-gl=\"frat\">FRAT</a> records the hazard and the escape plan&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-5\">[5, ch. 3]</a></span>.</li>\n</ul>\n\n<h2>Where do icing forecasts fit in a disciplined decision?</h2>\n<p>PlaneWX is decision support for general aviation pilots, built around one idea: \"Fly like it's your job.\" Treat the weather decision the way a professional crew would, with the same process every time. That process is a loop: <span class=\"loop\">Brief, then FRAT, then Fly or Stay, then Debrief</span>, with a Mentor if you want one. Icing products feed the Brief. Here's how PlaneWX handles them, as described in the help center&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-6\">[6]</a></span>:</p>\n<ul>\n  <li><strong>Brief: which icing data.</strong> On CONUS flights within 18 hours of departure, PlaneWX layers the FAA/NWS CIP nowcast and the DAFS Icing Forecast Integration forecast over icing soundings from several weather models (<a href=\"https://app.planewx.ai/help/icing-analysis\">Icing Analysis</a>).</li>\n  <li><strong>Brief: no cloud, no ice.</strong> When model soundings show cloud tops at or below the freezing level, PlaneWX zeros that waypoint's icing severity even if the icing product still paints it, and the briefing explains why (<a href=\"https://app.planewx.ai/help/icing-analysis\">Icing Analysis</a>).</li>\n  <li><strong>Brief: severe is severe.</strong> \"PlaneWX always marks severe icing as unfavorable regardless of aircraft equipment.\" (<a href=\"https://app.planewx.ai/help/icing-analysis\">Icing Analysis</a>)</li>\n  <li><strong>FRAT.</strong> The flight risk assessment opens within 4 hours of departure, and your own ratings drive it (<a href=\"https://app.planewx.ai/help/frat\">FRAT</a>).</li>\n  <li><strong>Fly or Stay.</strong> \"PlaneWX never recommends GO or NO-GO. You make the call as PIC.\" (<a href=\"https://app.planewx.ai/help/risk-loop\">The Risk Loop</a>)</li>\n  <li><strong>Debrief.</strong> If you picked up ice, the debrief is the moment to file the PIREP. Self Debrief is a PlaneWX Labs feature for Pro Plus (<a href=\"https://app.planewx.ai/help/risk-loop\">The Risk Loop</a>).</li>\n</ul>\n<p>The help center is plain about the limits: \"PlaneWX is not a substitute for a complete, independent pre-flight weather briefing. Pull one from a source you already trust before you fly.\" (<a href=\"https://app.planewx.ai/help/risk-loop\">The Risk Loop</a>)</p>\n\n<!-- Screenshot slots (dark mode; Chief of Staff review required before adding; real trips only, blur tail numbers and names):\n     S1: Icing tile with CIP/IFI source label and freezing level.\n     S2: Altitude Advisor icing column at several altitudes. -->\n\n<p><a href=\"https://app.planewx.ai/\">See the icing picture along your next route in a PlaneWX briefing</a>, or read <a href=\"https://app.planewx.ai/help/icing-analysis\">how PlaneWX analyzes icing</a>. Related: the PlaneWX guide to <a href=\"https://www.planewx.ai/blog/icing-forecast-for-small-aircraft\">icing forecasts for small aircraft</a>.</p>\n\n<nav class=\"hub-related\" aria-labelledby=\"related-h\">\n<h2 id=\"related-h\">More from the PlaneWX Learning Center</h2>\n<ul>\n  <li><a href=\"/learn/aviation-weather/taf\">What Is a TAF? How to Read a Terminal Aerodrome Forecast</a>. The airport forecast, with FM, TEMPO, PROB30, and a full worked decode.</li>\n  <li><a href=\"/learn/aviation-weather/metar\">What Is a METAR? How to Read an Airport Weather Report</a>. The airport observation, every group decoded, plus when a SPECI is issued.</li>\n  <li><a href=\"/learn/aviation-weather/airmet-sigmet\">AIRMET, SIGMET, and CWA: In-Flight Weather Advisories Explained</a>. G-AIRMETs, SIGMETs, Convective SIGMETs, and Center Weather Advisories, with decoded samples.</li>\n  <li><a href=\"/learn/aviation-weather/pirep\">What Is a PIREP? How to Read and Give a Pilot Weather Report</a>. The UA and UUA format, the icing and turbulence scales, and how to give one.</li>\n  <li><a href=\"/learn/aviation-weather/winds-aloft\">Winds and Temperatures Aloft: How to Read an FB Forecast</a>. The FB code decoded, including winds over 100 knots, and how model winds differ.</li>\n  <li><a href=\"/learn/aviation-weather/turbulence\">Turbulence Forecasts: GTG, GTG-N, and the Intensity Scale</a>. The automated turbulence forecast and nowcast, EDR, and the advisories that cover what GTG does not.</li>\n  <li><a href=\"/learn/aviation-weather/weather-radar\">Weather Radar for Pilots: NEXRAD, TDWR, Reflectivity, and Datalink Delay</a>. How to read radar images, their blind spots, and why cockpit mosaics are older than they look.</li>\n  <li><a href=\"/learn/aviation-weather/density-altitude\">Density Altitude Calculator and Guide: What It Is and How to Calculate It</a>. The FAA definition, the formulas, a worked example, a calculator, and the Koch chart.</li>\n  <li><a href=\"/learn/flight-risk-assessment-tool\">Flight Risk Assessment Tool (FRAT): What It Is and How to Use One Honestly</a>. Where the FAA FRAT comes from, how the scores work, and how to fill one out without fooling yourself.</li>\n</ul>\n</nav>\n\n<section class=\"faq\">\n<h2>Frequently asked questions</h2>\n\n<h3>What is the difference between CIP and FIP?</h3>\n<p>The CIP is an hourly diagnosis of icing built from satellite, radar, METARs, PIREPs, and model data. The FIP is its forecast counterpart, based on computer models, out to 18 hours. Both are automated, with no forecaster changes&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.5 and 27.13]</a></span>.</p>\n\n<h3>Does the CIP show current icing?</h3>\n<p>Not exactly. Despite the name, the Handbook says it shows the computer's expected conditions at the product's valid time, and \"This valid time can be an hour old or more depending on when it is received by the user.\"&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span></p>\n\n<h3>What does heavy icing mean on the FIP?</h3>\n<p>\"Heavy icing is defined as the accretion of ¼ inch of ice on the airfoil in < 15 minutes.\" The Handbook calls it a relative value that depends on the airframe and its ice protection&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13]</a></span>.</p>\n\n<h3>Is FIP heavy icing the same as severe icing?</h3>\n<p>No. CIP and FIP categories are a broad indication of ice accumulation rate, not of aircraft performance&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.5]</a></span>. The AIM's severe icing is defined by what happens to the aircraft: ice protection can't keep up and immediate exit is required&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-19]</a></span>.</p>\n\n<h3>What is the freezing level?</h3>\n<p>\"The freezing level is the lowest altitude in the atmosphere over a given location at which the air temperature reaches 0°C.\" There can be more than one&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 25.4]</a></span>.</p>\n\n<h3>Where do I find the freezing level?</h3>\n<p>The freezing level analysis and forecast graphics, updated hourly&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, paras. 25.4 and 27.12]</a></span>; AIRMET Zulu&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-4\">[4, sec. 7.1]</a></span>; and PIREP temperatures and the temperatures in the winds aloft forecast&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-1]</a></span>.</p>\n\n<h3>What are supercooled large drops?</h3>\n<p>Liquid drops larger than 50 micrometers, 0.05 mm, below 0°C, such as freezing drizzle and freezing rain&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 27.13.3]</a><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-20]</a></span>. They can freeze behind the protected areas&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-1\">[1, para. 20.3.2.1]</a></span>.</p>\n\n<h3>Can a report of no icing be trusted?</h3>\n<p>Only for that time and place. The AIM notes that a report of no icing can't assure the absence of icing later&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-2\">[2, para. 7-1-20]</a></span>. Negative icing PIREPs still help forecasters&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-3\">[3, para. 4-3]</a></span>.</p>\n\n<h3>How does PlaneWX use CIP and FIP?</h3>\n<p>On CONUS flights within 18 hours, the help center says PlaneWX layers the CIP nowcast and the DAFS Icing Forecast Integration, which it describes as the successor to FIP, over multi-model icing soundings. PlaneWX never recommends GO or NO-GO; you make the call as PIC&nbsp;<span class=\"cites\"><a class=\"cite\" href=\"#ref-6\">[6]</a></span>.</p>\n</section>\n\n<section class=\"glossary\" id=\"glossary\" aria-labelledby=\"glossary-h\">\n<h2 id=\"glossary-h\">Glossary</h2>\n<p>Every term below links to the FAA, NWS, or NOAA document that defines it. The same definitions appear when you hover, focus, or tap a dotted term on this page.</p>\n<dl>\n  <dt id=\"gl-zulu\"><dfn>AIRMET Zulu</dfn></dt>\n  <dd>The AIRMET series for moderate icing; it also gives freezing level heights. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=383\">FAA Aviation Weather Handbook, 26.3.1.2</a></span></dd>\n  <dt id=\"gl-cip\"><dfn>CIP</dfn> (Current Icing Product)</dt>\n  <dd>An hourly, automated 3D diagnosis of icing probability, severity, and supercooled large drop threat, built from satellite, radar, METARs, PIREPs, and model data. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=365\">FAA Aviation Weather Handbook, 25.5</a></span></dd>\n  <dt id=\"gl-csigmet\"><dfn>Convective SIGMET</dfn></dt>\n  <dd>The SIGMET issued for thunderstorms over the contiguous U.S. It implies severe or greater turbulence, severe icing, and low-level wind shear. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=374\">FAA Aviation Weather Handbook, 26.2.4.2</a></span></dd>\n  <dt id=\"gl-cwa\"><dfn>CWA</dfn> (Center Weather Advisory)</dt>\n  <dd>A short-term advisory from a Center Weather Service Unit for weather that meets or approaches AIRMET or SIGMET criteria, valid for up to 2 hours. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=387\">FAA Aviation Weather Handbook, 26.4</a></span></dd>\n  <dt id=\"gl-fip\"><dfn>FIP</dfn> (Forecast Icing Product)</dt>\n  <dd>The automated forecast counterpart of the CIP: icing probability, severity, and supercooled large drop threat out to 18 hours, from computer model output. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=454\">FAA Aviation Weather Handbook, 27.13</a></span></dd>\n  <dt id=\"gl-frat\"><dfn>FRAT</dfn> (Flight Risk Assessment Tool)</dt>\n  <dd>A form or checklist for recording flight hazards and the risk they add up to before you fly. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/2022-06/risk_management_handbook_2A.pdf#page=28\">FAA Risk Management Handbook, Chapter 3, Using a Flight Risk Assessment Tool (FRAT)</a></span></dd>\n  <dt id=\"gl-frzlvl\"><dfn>Freezing level</dfn></dt>\n  <dd>The lowest altitude over a place where the air temperature reaches 0°C. There can be more than one. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=365\">FAA Aviation Weather Handbook, 25.4</a></span></dd>\n  <dt id=\"gl-pirep\"><dfn>PIREP</dfn> (Pilot Weather Report)</dt>\n  <dd>A report of weather a pilot actually encountered in flight, shared to help other pilots and forecasters. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=310\">FAA Aviation Weather Handbook, 24.5.1</a></span></dd>\n  <dt id=\"gl-sigmet\"><dfn>SIGMET</dfn> (Significant Meteorological Information)</dt>\n  <dd>An unscheduled warning of en route weather that may affect the safety of aircraft operations, such as severe icing, severe turbulence, widespread dust storms or sandstorms, and volcanic ash. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=369\">FAA Aviation Weather Handbook, 26.2</a></span></dd>\n  <dt id=\"gl-sld\"><dfn>SLD</dfn> (Supercooled large drops)</dt>\n  <dd>Liquid water drops larger than 50 micrometers, such as freezing drizzle and freezing rain, that stay unfrozen below 0°C and can freeze behind ice protection. <span class=\"src\">Source: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf#page=455\">FAA Aviation Weather Handbook, 27.13.3</a></span></dd>\n</dl>\n</section>\n\n<p class=\"note\">This page explains published FAA and NWS guidance. It is not a substitute for your aircraft's flight manual limits on flight in icing. Always get a current briefing before you fly.</p>\n\n<section class=\"refs\" aria-labelledby=\"references\">\n<h2 id=\"references\">References</h2>\n<ol>\n  <li id=\"ref-1\">FAA-H-8083-28B, \"Aviation Weather Handbook.\" Federal Aviation Administration, Flight Standards Service. April 2, 2026. Paragraphs cited: 3.4.2.7 (Table 3-10), 3.4.2.8 (Table 3-11), 15.2.15.1.5, 20.3.2.1, 25.4, 25.5, 27.12, 27.13, 27.13.1 to 27.13.3. <a href=\"https://www.faa.gov/regulationspolicies/handbooksmanuals/aviation/faa-h-8083-28b-aviation-weather-handbook\">https://www.faa.gov/regulationspolicies/handbooksmanuals/aviation/faa-h-8083-28b-aviation-weather-handbook</a>. PDF: <a href=\"https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf\">https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf</a></li>\n  <li id=\"ref-2\">\"7-1-19. PIREPs Relating to Airframe Icing\" and \"7-1-20. Definitions of Inflight Icing Terms.\" Aeronautical Information Manual (AIM), Chapter 7, Section 1. Federal Aviation Administration. Effective July 9, 2026 (Change 3). <a href=\"https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap7_section_1.html\">https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap7_section_1.html</a></li>\n  <li id=\"ref-3\">AC 91-74B, \"Pilot Guide: Flight in Icing Conditions.\" Federal Aviation Administration. October 8, 2015. Paragraphs cited: 1-3, 4-1, 4-1c, 4-1g, 4-1h, 4-3. <a href=\"https://www.faa.gov/documentLibrary/media/Advisory_Circular/AC_91-74B.pdf\">https://www.faa.gov/documentLibrary/media/Advisory_Circular/AC_91-74B.pdf</a></li>\n  <li id=\"ref-4\">NWS Instruction 10-811, \"En Route Forecasts and Advisories.\" National Weather Service. September 2, 2025. Section 7.1. <a href=\"https://www.weather.gov/media/directives/010_pdfs/pd01008011curr.pdf\">https://www.weather.gov/media/directives/010_pdfs/pd01008011curr.pdf</a></li>\n  <li id=\"ref-5\">FAA-H-8083-2A, \"Risk Management Handbook.\" Federal Aviation Administration. 2022. Chapter 3, \"Using a Flight Risk Assessment Tool (FRAT).\" <a href=\"https://www.faa.gov/regulationspolicies/handbooksmanuals/risk-management-handbook-faa-h-8083-2a\">https://www.faa.gov/regulationspolicies/handbooksmanuals/risk-management-handbook-faa-h-8083-2a</a></li>\n  <li id=\"ref-6\">PlaneWX Help Center: \"Icing Analysis,\" \"FRAT,\" \"The Risk Loop.\" PlaneWX. Accessed September 29, 2026. <a href=\"https://app.planewx.ai/help/icing-analysis\">Icing Analysis</a> · <a href=\"https://app.planewx.ai/help/frat\">FRAT</a> · <a href=\"https://app.planewx.ai/help/risk-loop\">The Risk Loop</a></li>\n</ol>\n</section>\n</div>\n\n</article>"
export const INLINE_STYLE = "\n  :root {\n    --bg: #ffffff; --fg: #1b1f24; --muted: #57606a; --line: #d0d7de;\n    --card: #f6f8fa; --accent: #0b5cad; --quote: #eef4fb;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --bg: #0f1419; --fg: #e6e8eb; --muted: #9aa4af; --line: #2d3640;\n      --card: #161d24; --accent: #6cb4ff; --quote: #142231;\n    }\n  }\n  * { box-sizing: border-box; }\n  html { -webkit-text-size-adjust: 100%; }\n  body { margin: 0; background: var(--bg); color: var(--fg);\n    font: 18px/1.65 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif; }\n  main { max-width: 760px; margin: 0 auto; padding: 32px 20px 64px; }\n  h1 { font-size: 2.05rem; line-height: 1.2; margin: 0 0 12px; }\n  h2 { font-size: 1.45rem; line-height: 1.3; margin: 44px 0 12px; padding-top: 8px; border-top: 1px solid var(--line); }\n  h3 { font-size: 1.12rem; margin: 26px 0 8px; }\n  p, ul, ol { margin: 0 0 16px; }\n  li { margin: 0 0 6px; }\n  a { color: var(--accent); }\n  .byline { color: var(--muted); font-size: 0.92rem; margin-bottom: 24px; }\n  .answer { background: var(--card); border: 1px solid var(--line); border-left: 4px solid var(--accent);\n    border-radius: 8px; padding: 16px 18px; font-size: 1.06rem; margin: 0 0 20px; }\n  .takeaways { background: var(--card); border: 1px solid var(--line); border-radius: 8px; padding: 14px 18px 4px; margin: 0 0 24px; }\n  .takeaways h2 { border: 0; margin: 0 0 8px; padding: 0; font-size: 1.05rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); }\n  blockquote { margin: 0 0 18px; padding: 12px 16px; background: var(--quote); border-left: 4px solid var(--accent); border-radius: 6px; }\n  blockquote p:last-child { margin-bottom: 0; }\n  blockquote footer { color: var(--muted); font-size: 0.9rem; margin-top: 6px; }\n  .cite { font-size: 0.78em; vertical-align: super; line-height: 0; text-decoration: none; white-space: nowrap; }\n  .cite:hover { text-decoration: underline; }\n  .cite + .cite { margin-left: 0.25em; }\n  table { width: 100%; border-collapse: collapse; margin: 0 0 20px; font-size: 0.95rem; }\n  th, td { border: 1px solid var(--line); padding: 10px 12px; vertical-align: top; text-align: left; }\n  th { background: var(--card); }\n  .checklist { background: var(--card); border: 1px solid var(--line); border-radius: 8px; padding: 14px 18px 6px; margin: 0 0 20px; }\n  .checklist h3 { margin-top: 10px; }\n  .checklist ul { list-style: none; padding-left: 0; }\n  .checklist li::before { content: \"\\2610\"; margin-right: 8px; color: var(--muted); }\n  .faq h3 { margin-top: 22px; }\n  .note { color: var(--muted); font-size: 0.95rem; font-style: italic; }\n  .refs ol { padding-left: 1.4em; font-size: 0.93rem; }\n  .refs li { margin-bottom: 10px; word-break: break-word; }\n  .refs li:target { background: var(--quote); outline: 2px solid var(--accent); border-radius: 4px; }\n  .loop { font-weight: 600; }\n  /* ---- Hub layout: header, Key Facts sidebar, body (PlaneWX /learn/aviation-weather template) ---- */\n  main.hub-main { max-width: 1120px; }\n  .hub { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 40px; }\n  .hub-head, .keyfacts, .hub-body { min-width: 0; }\n  /* ---- Sub-headings: real h3, semibold, about 1.13x body, clear space above ---- */\n  .hub h3 { font-size: 1.13em; font-weight: 600; line-height: 1.35; margin: 36px 0 10px; }\n  .hub .faq h3 { margin-top: 32px; }\n  .hub .fieldref h3 { margin-top: 4px; }\n  /* ---- Citations stay on the line of the word before them ---- */\n  /* A cite group never breaks inside, at any width (including Key Facts). Groups too long for the narrowest\n     container are split in the source so each cite sits right after its claim. */\n  .cites { white-space: nowrap; }\n  .cite + .cite { margin-left: 0; }  /* no gap before a cite that follows a cite */\n  /* ---- Key Facts ---- */\n  .kf-box { background: var(--card); border: 1px solid var(--line); border-top: 4px solid var(--accent);\n    border-radius: 8px; padding: 12px 16px 4px; margin: 0 0 24px; font-size: 0.86rem; line-height: 1.42; }\n  .kf-box summary { list-style: none; cursor: pointer; display: flex; align-items: center; justify-content: space-between; }\n  .kf-box summary::-webkit-details-marker { display: none; }\n  .kf-box summary::after { content: \"Show\"; font-size: 0.8rem; color: var(--accent); font-weight: 600; }\n  .kf-box[open] summary::after { content: \"Hide\"; }\n  .kf-box h2 { border: 0; margin: 0; padding: 0; font-size: 1rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); }\n  .kf-box ol { margin: 8px 0 6px; padding-left: 1.25em; }\n  .kf-box li { margin: 0 0 6px; }\n  .kf-box .kf-foot { color: var(--muted); font-size: 0.78rem; margin: 2px 0 8px; }\n  .kf-fade { display: none; }\n  /* ---- Official field reference box ---- */\n  .fieldref { background: var(--quote); border: 1px solid var(--line); border-left: 4px solid var(--accent); border-radius: 8px; padding: 14px 18px 6px; margin: 0 0 22px; }\n  .fieldref .status { color: var(--muted); font-size: 0.85rem; }\n  /* ---- Raw code blocks (TAF, METAR, etc.) ---- */\n  .raw-wrap { position: relative; margin: 0 0 8px; }\n  pre.taf-raw { background: var(--card); border: 1px solid var(--line); border-radius: 8px; padding: 14px 16px; overflow-x: auto; margin: 0;\n    font: 0.95rem/1.9 ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace;\n    scrollbar-width: thin; scrollbar-color: var(--muted) var(--line); }\n  pre.taf-raw::-webkit-scrollbar { height: 8px; }\n  pre.taf-raw::-webkit-scrollbar-track { background: var(--line); border-radius: 0 0 8px 8px; }\n  pre.taf-raw::-webkit-scrollbar-thumb { background: var(--muted); border-radius: 4px; }\n  pre.taf-raw:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n  pre.taf-raw .tk { color: inherit; }\n  .scroll-note { display: none; }\n  .decode-cap { color: var(--muted); font-size: 0.88rem; margin: 0 0 18px; }\n  .table-intro { color: var(--muted); font-size: 0.92rem; margin: 0 0 8px; text-align: left; }\n  /* ---- Tables ---- */\n  table.decode td:first-child { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace; overflow-wrap: anywhere; }\n  table.decode tr:target td { background: var(--quote); }\n  table.times td, table.times th { white-space: nowrap; }\n  table.times th { white-space: normal; }\n  .table-wrap { overflow-x: auto; margin: 0 0 20px; }\n  .table-wrap table { margin: 0; }\n  code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace; font-size: 0.92em; }\n  /* ---- On-page glossary (no-JS fallback and tooltip anchor targets) ---- */\n  .glossary dl { margin: 0 0 16px; }\n  .glossary dt { font-size: 1rem; font-weight: 600; margin-top: 14px; }\n  .glossary dfn { font-style: normal; }\n  .glossary dt:target, .glossary dt:target + dd { background: var(--quote); }\n  .glossary dd { margin: 2px 0 0; font-size: 0.95rem; }\n  .glossary .src { color: var(--muted); font-size: 0.85rem; }\n  /* ---- Below 600 px: stacked-card tables, scroll hint and fade on raw blocks ---- */\n  @media (max-width: 599.98px) {\n    table.stack, table.stack tbody, table.stack tr, table.stack td, table.stack th[scope=\"row\"] { display: block; width: 100%; }\n    table.stack thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }\n    table.stack tr { border: 1px solid var(--line); border-radius: 8px; margin: 0 0 12px; overflow: hidden; }\n    table.stack td, table.stack th[scope=\"row\"] { border: 0; border-top: 1px solid var(--line); padding: 8px 12px; }\n    table.stack tr > :first-child { border-top: 0; }\n    table.stack th[scope=\"row\"], table.decode td:first-child { background: var(--card); font-weight: 600; }\n    table.stack td[data-label]::before { content: attr(data-label); display: block; font: 600 0.74rem/1.4 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n      text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin-bottom: 2px; }\n    table.decode td:first-child::before { display: none; }\n    .table-wrap:has(table.stack) { overflow: visible; }\n    .scroll-note { display: block; color: var(--muted); font-size: 0.82rem; margin: 0 0 6px; }\n    .raw-wrap::after { content: \"\"; position: absolute; top: 1px; right: 1px; bottom: 9px; width: 40px; pointer-events: none;\n      border-radius: 0 8px 0 0; background: linear-gradient(to right, rgba(0,0,0,0), var(--card)); transition: opacity .15s; }\n    .raw-wrap.at-end::after { opacity: 0; }\n    table.times { font-size: 0.88rem; }\n    table.times th, table.times td { padding: 8px 7px; }\n  }\n  /* ---- Desktop: two columns, sticky Key Facts (kept last so it overrides the mobile toggle styles) ---- */\n  @media (min-width: 980px) {\n    .hub { grid-template-columns: minmax(0, 760px) 320px; justify-content: center; }\n    .hub-head { grid-column: 1; grid-row: 1; }\n    .hub-body { grid-column: 1; grid-row: 2; }\n    .keyfacts { grid-column: 2; grid-row: 1 / span 2; }\n    /* Capped only when taller than the viewport; a bottom fade shows while more facts are below. */\n    .keyfacts .kf-box { position: sticky; top: 16px; max-height: calc(100vh - 32px); overflow-y: auto; }\n    .keyfacts summary { pointer-events: none; }\n    .keyfacts .kf-box summary::after, .keyfacts .kf-box[open] summary::after { content: none; }\n    .kf-box.is-capped .kf-fade { display: block; position: sticky; bottom: -4px; height: 36px; margin: -36px -16px 0; pointer-events: none;\n      background: linear-gradient(to bottom, rgba(0,0,0,0), var(--card)); }\n    .kf-box.is-capped.at-end .kf-fade { opacity: 0; }\n  }\n  /* ---- Glossary tooltip (hover, keyboard focus, tap). No framework. ---- */\n  a.gl { color: inherit; text-decoration: underline dotted; text-decoration-thickness: 1px; text-underline-offset: 3px; cursor: help; }\n  a.gl:hover, a.gl[aria-expanded=\"true\"] { color: var(--accent); text-decoration-style: solid; }\n  a.gl:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }\n  .gl-tip { position: fixed; z-index: 1000; max-width: min(340px, calc(100vw - 24px)); background: var(--bg); color: var(--fg);\n    border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 6px 24px rgba(0,0,0,.18); padding: 10px 12px;\n    font: 0.88rem/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif; white-space: normal; text-align: left; }\n  .gl-tip[hidden] { display: none; }\n  .gl-tip .gl-t { display: block; font-weight: 700; }\n  .gl-tip .gl-x { display: block; color: var(--muted); font-size: 0.82rem; margin-bottom: 4px; }\n  .gl-tip .gl-d { display: block; margin-bottom: 6px; }\n  .gl-tip .gl-s { display: block; font-size: 0.8rem; }\n  .gl-tip .gl-s a { color: var(--accent); }\n  @media (prefers-reduced-motion: no-preference) { .gl-tip { transition: opacity .12s; } }\n"
